SOURCE_CLAIM_JSON: {"title":"The Constitution of the Islamic Republic of Iran","publisher":"University of Minnesota Human Rights Library","publication_date":"1979-1989 constitutional text","url":"https://hrlibrary.umn.edu/research/iran-constitution.html","claim":"The constitution makes the Guardian Council partly Leader-selected and gives it responsibility for supervising elections for the President, Assembly of Experts, Majles, and referenda.","locator":"Articles 91 and 99; lines 481-509","source_type":"legal","source_confidence":"high","source_confidence_reason":"Primary constitutional text describing the formal election-supervision architecture.","final_evidence_use":"final_evidence","period_fit":"Stable baseline applicable in 2022.","ruler_attribution":"Directly attributable to the institutional design Khamenei operated within and helped control.","contrary_evidence":["This is formal design, not proof of fair competition in practice.","It shows supervision, not competitive neutrality."],"lenses":["4B.1","4B.2","4B.4","4B.8"]}
SOURCE_CLAIM_JSON: {"title":"The Constitution of the Islamic Republic of Iran","publisher":"University of Minnesota Human Rights Library","publication_date":"1979-1989 constitutional text","url":"https://hrlibrary.umn.edu/research/iran-constitution.html","claim":"The constitution nominally allows press freedom, association, assembly, and narrow arrest procedures, but only within Islamic/public-order limits and with censorship and detention carve-outs.","locator":"Articles 24-27 and 32; lines 217-228, 246-247","source_type":"legal","source_confidence":"high","source_confidence_reason":"Primary constitutional text showing formal liberties and their sharp exceptions.","final_evidence_use":"context","period_fit":"Stable baseline applicable in 2022.","ruler_attribution":"Relevant as nominal rights existing under Khamenei's regime, not as evidence of real protection.","contrary_evidence":["The clauses are heavily qualified and did not prevent the 2022 crackdown.","Formal rights on paper are weaker than lived political freedom."],"lenses":["4B.3","4B.6","4B.9"]}
